 * @param {any} input - The input to validate
 * @param {string} fieldName - Name of the field for error messages
 * @param {Object} options - Validation options
 * @returns {{ valid: boolean, value?: any, error?: string }}
 */
function validateInput(input, fieldName, options = {}) {
  const { 
    required = false, 
    type = 'string', 
    maxLength = Infinity, 
    minLength = 0,
    pattern = null 
  } = options;

  // Check required
  if (required && (input === undefined || input === null || input === '')) {
    return { valid: false, error: `${fieldName} is required` };
  }

  // Skip further validation if not required and empty
  if (input === undefined || input === null || input === '') {
    return { valid: true, value: null };
  }

  // Type validation
  if (type === 'string' && typeof input !== 'string') {
    return { valid: false, error: `${fieldName} must be a string` };
  }

  if (type === 'number' && typeof input !== 'number') {
    return { valid: false, error: `${fieldName} must be a number` };
  }

  // Length validation for strings
  if (type === 'string') {
    if (input.length > maxLength) {
      return { valid: false, error: `${fieldName} exceeds maximum length of ${maxLength}` };
    }
    if (input.length < minLength) {
      return { valid: false, error: `${fieldName} must be at least ${minLength} characters` };
    }
  }

  // Pattern validation (regex)
  if (pattern && !pattern.test(input)) {
    return { valid: false, error: `${fieldName} has invalid format` };
  }

  // Sanitize: trim whitespace, escape special chars for strings
  const sanitized = type === 'string' ? input.trim() : input;

  return { valid: true, value: sanitized };
